import assert from 'node:assert/strict';
import fs from 'node:fs';
import {emptyTags,resolved,rollTag,editTag,validateTags} from './engine.ts';
const def={id:'research.synthetic.A',version:1,label:{en:'Synthetic A'},resolver:'independent',slots:[{id:'row',sides:100}],tables:[Array.from({length:100},(_,i)=>({en:`payload${i+1}`}))]};
const owner={kind:'poi',regionId:1,hexKey:'0,0'};
const cases=[];
for(const n of [1,37,100]){const r=resolved(def,[[n]]);assert.equal(r.texts[0].en,`payload${n}`);cases.push({id:`DIRECT-${n}`,result:r});}
const initial=emptyTags(), first=rollTag(initial,owner,def,123);
assert.deepEqual(initial,emptyTags());assert.deepEqual(first,rollTag(initial,owner,def,123));
cases.push({id:'DETERMINISTIC-CLONE',passed:true,values:first.instances[0].values});
const second=rollTag(first,owner,def,123);assert.equal(second.instances.length,1);assert.equal(second.instances[0].revision,2);
cases.push({id:'REPEATED-TABLE-REPLACES',instances:second.instances.length,revision:2,interpretation:'Existing reroll semantics; not a Knave two-component recipe implementation.'});
const edited=editTag(first,owner,def.id,0,'en','GM interpretation');assert.deepEqual(edited.instances[0].values,first.instances[0].values);
assert.equal(edited.instances[0].overrides[0].en,'GM interpretation');
const roundtrip=JSON.parse(JSON.stringify(edited));validateTags(roundtrip,new Set(['poi:1:0,0']),{[def.id]:def});assert.deepEqual(roundtrip,edited);
cases.push({id:'TAG-JSON-ROUNDTRIP',passed:true,boundary:'Pure tag blob only; not App file import/export or Undo/Redo.'});
validateTags(roundtrip,new Set(['poi:1:0,0']),{});cases.push({id:'UNKNOWN-DEFINITION-PASSIVE',passed:true,boundary:'Structural acceptance is not UI registration or rule compatibility.'});
const out={source_sha:'7547a67bbcfb621f1e7c7189518583842ccb055a',module:'src/tags/engine.ts',synthetic_data:true,cases,limitations:['No browser/UI or full document transaction executed.','No actual Knave literary tables embedded.','No rule coverage/score awarded.']};
fs.writeFileSync(new URL('./probe-result.json',import.meta.url),JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify(out));
